/**
 * Test stub for the `#i18n` WXT virtual module.
 *
 * WHY THIS EXISTS
 *
 * `#i18n` is generated by `wxt prepare` into `.wxt/i18n/`. Vitest cannot resolve
 * it, and that had a consequence far worse than a failing import:
 *
 *   1. Every `.tsx` that imports `#i18n` could never be loaded by a unit test.
 *   2. So those files were never *covered* — they went through the suite as
 *      "untested files".
 *   3. To report 0% for an untested file, vitest-coverage-v8 transforms it with
 *      its own pipeline. That transform cannot resolve `#i18n` either, and the
 *      provider swallows the failure (`.catch(() => null)` in `getSources`),
 *      falling back to reading the RAW `.tsx` off disk.
 *   4. It then feeds raw TSX to rollup's JavaScript-only parser, which fails on
 *      the type annotations, and logs "Excluding it from coverage" — while
 *      still exiting 0.
 *
 * Net effect: four components were silently absent from `coverage-final.json`,
 * and the coverage thresholds were computed over a smaller file set than
 * `vitest.config.ts` asks for. The gate was green while measuring less than it
 * claimed. `scripts/check-coverage-integrity.mjs` now fails the build if that
 * ever happens again; this alias is the actual fix.
 *
 * WHY IT IS NOT A STRING-CONCATENATION FAKE
 *
 * `t()` resolves the real key against the real `en.yml`, and applies the real
 * `$1`/`$2` substitutions. A test that renders a component therefore sees the
 * actual user-visible English copy, so assertions on that copy are meaningful
 * and a broken locale key surfaces as the raw key rather than silently
 * rendering something plausible.
 *
 * This is the same module for the whole suite (aliased in `vitest.config.ts`),
 * so a test that wants to assert on a specific string does not need a mock and
 * a test that wants to assert on copy keeps working.
 */

import { readFileSync } from "fs";
import { resolve } from "path";
import { load } from "js-yaml";

type LocaleTree = { [key: string]: string | LocaleTree };

/**
 * A substitution value.
 *
 * `string | number`, matching `@wxt-dev/i18n`'s own `Substitution`. The stub
 * previously typed this as `string | string[]`, which was narrower than the
 * real API: the codebase passes a count as a bare number in dozens of places
 * (`i18n.t("importWizard.upload.foundSnippets", parsedSnippets.length)`), so
 * any test that copied a real call site would have failed to typecheck against
 * a stub that was supposed to stand in for it.
 */
type Substitution = string | number;

const enYaml = load(
  readFileSync(resolve(__dirname, "../../src/locales/en.yml"), "utf-8")
) as LocaleTree;

/**
 * Resolve a dotted key path (`"common.save"`) against the locale tree.
 *
 * A node is either a plain string, or a plural group written in en.yml as
 * `{ 1: ..., n: ... }`. WXT flattens the latter into a single Chrome message
 * with `|`-separated plural forms — `1: "Found 1 snippet"`, `n: "Found $1
 * snippets"` becomes `"Found 1 snippet | Found $1 snippets"` in the built
 * `_locales` file — and Chrome picks the form from the count.
 *
 * Plural nodes are returned as the ordered list of forms rather than being
 * discarded. Treating them as unresolvable made nine keys
 * (`importWizard.upload.foundSnippets`, `importWizard.footer.importCount`, and
 * seven others) echo their own dotted key into every test that touched them, so
 * a test asserting on pluralized copy was asserting on the key, not the words a
 * user reads.
 */
function lookup(key: string): string | string[] | undefined {
  let node: string | LocaleTree | undefined = enYaml;
  for (const segment of key.split(".")) {
    if (node === undefined || typeof node === "string") return undefined;
    node = node[segment];
  }
  if (typeof node === "string") return node;
  if (node && typeof node === "object") {
    // A plural group: every value a string, keyed by plural category.
    const forms = Object.values(node);
    if (forms.length > 0 && forms.every((f) => typeof f === "string")) {
      // `1` first, then the rest in declaration order, so index 0 is the
      // singular form regardless of how the YAML happens to be ordered.
      const singular = node["1"];
      const rest = forms.filter((f) => f !== singular);
      return typeof singular === "string" ? [singular, ...rest] : forms;
    }
  }
  return undefined;
}

/**
 * Choose the plural form for a count, using the English CLDR rule.
 *
 * English has two categories — "one" for exactly 1, "other" for everything
 * else — so a two-form message uses index 0 for 1 and index 1 otherwise. This
 * mirrors what Chrome does with the `|`-separated message it receives.
 */
function selectPlural(
  forms: string[],
  substitutions?: Substitution | Substitution[]
): string {
  const raw = Array.isArray(substitutions) ? substitutions[0] : substitutions;
  const count = Number(raw);

  // No usable count: take the first form. Picking the plural form here instead
  // would leave "$1" unsubstituted and render "Found $1 snippets" — half-built
  // copy in a stub whose purpose is to show what the user actually reads.
  if (!Number.isFinite(count)) return forms[0] ?? "";

  return forms[count === 1 ? 0 : 1] ?? forms[0] ?? "";
}

/**
 * Substitute `$1`, `$2`, … the way Chrome's i18n does.
 *
 * Accepts both the array form (`t(key, [a, b])`) and the bare-value form
 * (`t(key, n)`), because the codebase uses both — 34 call sites pass a second
 * argument and roughly half of them pass a non-array.
 */
function substitute(
  template: string,
  substitutions?: Substitution | Substitution[]
): string {
  const values: Substitution[] = Array.isArray(substitutions)
    ? substitutions
    : substitutions === undefined
      ? []
      : [substitutions];

  return template.replace(/\$(\d+)/g, (match, index: string) => {
    const value = values[Number(index) - 1];
    // An unmatched placeholder is left verbatim, matching Chrome's behaviour,
    // so a missing substitution is visible in the rendered output.
    // String() because a number substitution must become text — Chrome
    // substitutes strings, and React cannot render a bare number here.
    return value === undefined ? match : String(value);
  });
}

export const i18n = {
  /**
   * Translate `key`. Returns the key itself when it is missing from `en.yml`,
   * which makes a locale regression legible in a test failure instead of
   * rendering as an empty string.
   */
  t(key: string, substitutions?: Substitution | Substitution[]): string {
    const template = lookup(key);
    if (template === undefined) return key;
    if (Array.isArray(template)) {
      return substitute(selectPlural(template, substitutions), substitutions);
    }
    return substitute(template, substitutions);
  },

  getUILanguage(): string {
    return "en-US";
  },

  getMessage(
    key: string,
    substitutions?: Substitution | Substitution[]
  ): string {
    return i18n.t(key, substitutions);
  },
};

export default i18n;
